   392            /* And compose. */
   393            c.compose (&c,
   394                       buffer->out_info[starter].codepoint,
   395                       buffer->cur().codepoint,
   396                       &composed) &&
   397            /* And the font has glyph for the composite. */
   398            font->get_nominal_glyph (composed, &glyph))
